    var prev *Node
    current := head

    for current != nil {
        next := current.Next      // Guarda el siguiente
        current.Next = prev       // Invierte el puntero
        prev = current            // Avanza prev
        current = next            // Avanza current
    }

    return prev  // Nuevo head
}
```

## Enfoque recursivo

```go
func reverseRecursive(head *Node) *Node {
    if head == nil || head.Next == nil {
        return head
    }

    newHead := reverseRecursive(head.Next)
    head.Next.Next = head  // Invierte el puntero
    head.Next = nil         // Evita ciclos

    return newHead
}
```

## Ejemplo de uso

```go
func main() {
    // Crea: 1 -> 2 -> 3 -> nil
    head := &Node{Val: 1}
    head.Next = &Node{Val: 2}
    head.Next.Next = &Node{Val: 3}

    head = reverse(head)

    // Ahora: 3 -> 2 -> 1 -> nil
    for node := head; node != nil; node = node.Next {
        fmt.Println(node.Val)  // 3, 2, 1
    }
}
```

**Comparación:**
- **Iterativo**: O(n) tiempo, O(1) espacio — preferido para listas grandes
- **Recursivo**: O(n) tiempo, O(n) espacio (stack) — más elegante pero menos eficiente

